  // Check all the checkable args and make sure they all have types.
  val args = partitionArgs(iargs).getOrElse(return None)

  // A candidate with the declared arrow of a promoted one.
  type Ranked = (AppCandidate, Option[ArrowType])
  type Attempt = List[(Either[AppCandidate, OverloadingError], Option[ArrowType])]
  def moreSpecific(a: Ranked, b: Ranked) = moreSpecificCandidate(a._1, b._1, a._2, b._2)
  def isUnion(sarg: StaticArg) = sarg match {
    case STypeArg(_, false, _: UnionType) => true
    case _ => false
  }

  // Filter the overloadings that are applicable, by subtyping or with coercion.
  def applicable(ctx: Option[Type], coerce: Boolean): Attempt = preCandidates.map { pc =>
    checkApplicable(pc, ctx, args, mOpName, coerce) match {
      case Left(c) if !coerce && c.sargs.exists(isUnion) =>
        checkApplicable(pc, ctx, args, mOpName, false, Some(c.sargs.filter(!_.isLifted))) match {
          case Left(promoted) => (Left(promoted), Some(pc.arrow))
          case _ => (Left(c), None)
        }
      case e => (e, None)
    }
  }
  def candidatesOf(es: Attempt): List[Ranked] = es.collect { case (Left(c), d) => (c, d) }
  def kept(es: Attempt) = {
    val cs = candidatesOf(es)
    cs.nonEmpty && context.forall(c =>
      coercions.substitutableFor(cs.sortWith(moreSpecific).head._1.arrow.getRange, c))
  }
  lazy val withoutContext = applicable(None, false)
  val attempts: List[() => Attempt] =
    List(() => applicable(context, false), () => applicable(context, true)) ++
    (if (context.isDefined) List(() => withoutContext, () => applicable(None, true)) else Nil)
  lazy val first = attempts.head()
  val es = (first #:: attempts.tail.to(LazyList).map(_())).find(kept).getOrElse {
    if (fallBackWithoutContext && context.isDefined) withoutContext else first
  }
  val candidates = candidatesOf(es)
  val overloadingErrors = es.collect { case (Right(e), _) => e }

  // If there were no candidates, report errors.
  if (candidates.isEmpty) {
    errors.signal(errorFactory.makeApplicationError(overloadingErrors))
    return None
  }

  // Sort the arrows and instantiations to find the statically most
  // applicable. Then update each candidate's Overloading node.
