private def numeralTie[C](tied: List[(C, List[Type])], args: List[Either[Expr, FnExpr]]): Option[C] = {
  val exprs = args.map(_.left.toOption)
  val n = tied.head._2.size
  if (exprs.size != n || tied.exists(_._2.size != n)) return None
  val differ = (0 until n).filter(i => tied.exists(t => !Formula.isTrue(analyzer.equivalent(t._2(i), tied.head._2(i))))).toList
  if (differ.isEmpty || !differ.forall(i => exprs(i).exists(isNumeral))) return None
  val readings = differ.map(i => numeralReading(List(exprs(i).get)))
  if (readings.exists(_.isEmpty)) return None
  val fits = tied.filter(t => differ.zip(readings).forall { case (i, r) =>
    coercions.substitutableFor(r.get, t._2(i)) })
  def noWider(a: (C, List[Type]), b: (C, List[Type])) =
    differ.forall(i => coercions.noLessSpecific(a._2(i), b._2(i)))
  fits.find(a => fits.forall(noWider(a, _))).map(_._1)
}

